 const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
 function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
 function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
 function makeMap(){trees=[];rocks=[];buildings=[];for(let i=0;i<145;i++){let x=rand(45,W-45),y=rand(45,H-45);if(Math.hypot(x-W/2,y-H/2)<185)continue;trees.push({x,y,r:rand(13,25),tone:Math.random()})}for(let i=0;i<24;i++){let x=rand(100,W-120),y=rand(100,H-120);if(Math.hypot(x-W/2,y-H/2)<280)continue;buildings.push({x,y,w:rand(75,145),h:rand(58,110),rot:rand(-.08,.08)})}for(let i=0;i<58;i++)rocks.push({x:rand(50,W-50),y:rand(50,H-50),r:rand(7,15)})}
-function start(){playing=true;elapsed=0;kills=0;health=100;armor=50;ammo=30;reloading=false;zoneR=760;zoneStart=760;zoneTarget=120;zoneTimer=0;phase=0;bullets=[];loot=[];makeMap();player={x:W/2,y:H/2,r:14,speed:210,angle:0,cd:0,alive:true};bots=[];for(let i=0;i<14;i++){let a=rand(0,TAU),r=rand(380,710);bots.push({x:clamp(W/2+Math.cos(a)*r,40,W-40),y:clamp(H/2+Math.sin(a)*r,40,H-40),r:13,hp:100,angle:rand(0,TAU),speed:rand(82,112),cd:rand(.3,1.8),wander:rand(1,4),tx:0,ty:0,alive:true,flash:0,name:['GHOST','WRAITH','NOVA','KITE','MAMBA','ECHO','RUST','VEX','ONYX','FLINT','ASH','COBRA','ZERO','MOTH'][i]});}
+function start(){playing=true;elapsed=0;kills=0;health=100;armor=50;ammo=30;reloading=false;zoneR=760;zoneStart=760;zoneTarget=120;zoneTimer=0;phase=0;$('phase-label').textContent='ZONE 01';$('kill-count').textContent='0';$('weapon-state').textContent='READY';updateHUD();bullets=[];loot=[];makeMap();player={x:W/2,y:H/2,r:14,speed:210,angle:0,cd:0,alive:true};bots=[];for(let i=0;i<14;i++){let a=rand(0,TAU),r=rand(380,710);bots.push({x:clamp(W/2+Math.cos(a)*r,40,W-40),y:clamp(H/2+Math.sin(a)*r,40,H-40),r:13,hp:100,angle:rand(0,TAU),speed:rand(82,112),cd:rand(.3,1.8),wander:rand(1,4),tx:0,ty:0,alive:true,flash:0,name:['GHOST','WRAITH','NOVA','KITE','MAMBA','ECHO','RUST','VEX','ONYX','FLINT','ASH','COBRA','ZERO','MOTH'][i]});}
 for(let i=0;i<17;i++){let a=rand(0,TAU),r=rand(120,690);loot.push({x:clamp(W/2+Math.cos(a)*r,45,W-45),y:clamp(H/2+Math.sin(a)*r,45,H-45),type:Math.random()<.54?'ammo':Math.random()<.65?'med':'armor',pulse:rand(0,6)})}
 $('overlay').style.display='none';$('end-screen').style.display='none';game.classList.add('playing');$('top-status').textContent='ZONE CLOSING';$('top-alive').textContent='15 LEFT';requestAnimationFrame(loop)}
 function getObstacles(){return [...buildings.map(b=>({x:b.x+b.w/2,y:b.y+b.h/2,r:Math.min(b.w,b.h)*.39})),...rocks]}
 function blocked(x,y,r){for(const b of buildings){if(x>b.x-r&&x<b.x+b.w+r&&y>b.y-r&&y<b.y+b.h+r)return true}for(const t of trees)if(Math.hypot(x-t.x,y-t.y)<r+t.r*.48)return true;for(const o of rocks)if(Math.hypot(x-o.x,y-o.y)<r+o.r)return true;return false}

content.text:
+ // winding dirt tracks
+ ctx.strokeStyle='#9a8b61';ctx.lineWidth=28;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-80,400);ctx.bezierCurveTo(450,550,650,180,1080,360);ctx.bezierCurveTo(1500,540,1570,980,2290,800);ctx.stroke();ctx.strokeStyle='#c2b37c55';ctx.lineWidth=2;ctx.setLineDash([12,14]);ctx.stroke();ctx.setLineDash([]);
+ // pond
+ let pond=ctx.createRadialGradient(400,1180,15,400,1180,170);pond.addColorStop(0,'#426d6a');pond.addColorStop(1,'#365b54');ctx.fillStyle=pond;ctx.beginPath();ctx.ellipse(400,1180,175,105,-.2,0,TAU);ctx.fill();ctx.strokeStyle='#b9c68a77';ctx.lineWidth=5;ctx.stroke();
+ // zone safe field and ring
+ ctx.save();ctx.beginPath();ctx.arc(W/2,H/2,zoneR,0,TAU);ctx.fillStyle='rgba(200,241,105,.045)';ctx.fill();ctx.restore();ctx.beginPath();ctx.arc(W/2,H/2,zoneR,0,TAU);ctx.strokeStyle='rgba(211,250,128,.88)';ctx.lineWidth=3;ctx.setLineDash([12,9]);ctx.stroke();ctx.setLineDash([]);
+ // buildings
+ for(const b of buildings){ctx.save();ctx.translate(b.x+b.w/2,b.y+b.h/2);ctx.rotate(b.rot);ctx.fillStyle='#18251e55';rounded(-b.w/2+7,-b.h/2+8,b.w,b.h,5);ctx.fill();ctx.fillStyle='#827d62';rounded(-b.w/2,-b.h/2,b.w,b.h,4);ctx.fill();ctx.strokeStyle='#c8bf91';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#4b5c49';ctx.fillRect(-b.w*.24,-b.h*.19,b.w*.48,b.h*.38);ctx.fillStyle='#d3c795';ctx.fillRect(-b.w*.08,-b.h*.5,b.w*.16,b.h);ctx.restore()}
+ // loot
+ for(const l of loot){l.pulse+=.06;let c=l.type==='med'?'#d9f089':l.type==='armor'?'#83d3f0':'#f1bd61';ctx.save();ctx.translate(l.x,l.y);ctx.globalAlpha=.78+Math.sin(l.pulse)*.2;ctx.shadowColor=c;ctx.shadowBlur=14;ctx.fillStyle=c;ctx.beginPath();ctx.arc(0,0,8+Math.sin(l.pulse)*1.3,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#263323';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(l.type==='med'?'＋':l.type==='armor'?'⬟':'•',0,0);ctx.restore()}
+ // rocks
+ for(const o of rocks){ctx.fillStyle='#26382d';ctx.beginPath();ctx.ellipse(o.x+3,o.y+5,o.r*1.1,o.r*.8,0,0,TAU);ctx.fill();ctx.fillStyle='#77816d';ctx.beginPath();ctx.arc(o.x,o.y,o.r,0,TAU);ctx.fill();ctx.strokeStyle='#a2a38a';ctx.lineWidth=2;ctx.stroke()}
+ // bullets
+ for(const q of bullets){ctx.strokeStyle=q.player?'#e7ff9a':'#ffb275';ctx.lineWidth=q.player?3:2;ctx.beginPath();ctx.moveTo(q.x-q.vx*.025,q.y-q.vy*.025);ctx.lineTo(q.x,q.y);ctx.stroke();ctx.fillStyle='#fff8c7';ctx.beginPath();ctx.arc(q.x,q.y,2,0,TAU);ctx.fill()}
+ // characters
+ for(const b of bots)if(b.alive)drawActor(b,false);if(player)drawActor(player,true);
+ // trees in foreground layer
+ for(const t of trees){let shade=['#294b32','#31543a','#385d3c'][Math.floor(t.tone*3)];ctx.fillStyle='#1b3025';ctx.beginPath();ctx.ellipse(t.x+5,t.y+8,t.r*1.1,t.r*.78,0,0,TAU);ctx.fill();ctx.fillStyle=shade;ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,TAU);ctx.fill();ctx.strokeStyle='#668250';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#77905a66';ctx.beginPath();ctx.arc(t.x-t.r*.22,t.y-t.r*.25,t.r*.42,0,TAU);ctx.fill()}
